    int xl = max(x - 1, 0);
    int xr = min(x + 1, w - 1);
    int zu = max(z - 1, 0);
    int zd = min(z + 1, h - 1);
    float gx = (T[uint(z) * P.w + uint(xr)] - T[uint(z) * P.w + uint(xl)]) / (float(xr - xl) * P.cell);
